import { MainWrapper, Headline, Subheadline } from "./index.stitches";

function Topper() {
  return (
    <header>
      <MainWrapper>
        <ContentWrapper>
        <Headline>Hi, I'm Agnes!</Headline>
        <Subheadline>I am currently a D.C.-based Designer at The
        Washington Post, where I design and develop interactive stories.</Subheadline>
        </ContentWrapper>
      </MainWrapper>
    </header>
  );
}

export default Topper;
